test('invoiceTotals subtracts voucher from total', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;

  const resultWithoutVoucher = invoiceTotals(invoice);
  const voucherAmount = 1000;

  const voucherResult = applyVoucher(invoice, { code: 'PROMO10', amount: voucherAmount });
