test('createInvoice preserves terms when issuing invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const invoice = invoiceResult.value;

  const issuedResult = issueInvoice(invoice, []);
  assert.equal(issuedResult.value.terms, 'NET14');
  assert.equal(issuedResult.value.dueDate, '2025-10-21');
});

